// variationAttributes entry's `values[].value` is matched against the sibling variationValues
// code, and its `.name` is what renders — "Lilac Sand" / "One Size" here, joined by
// CartItemVariantAttributes' own `combineAttributeValues` into "Lilac Sand, One Size".
const MOCK_LINE_ITEM = {
  itemId: 'a1b2c3d4e5f6a1b2c3d4e5f6',
  productId: '25595021M',
  id: '25595021M',
  productName: 'Lilac Sand Silk Midi Dress',
  name: 'Lilac Sand Silk Midi Dress',
  price: 495,
  priceAfterItemDiscount: 495,
  pricePerUnit: 495,
  quantity: 1,
  stepQuantity: 1,
  minOrderQuantity: 1,
  imageGroups: [{ viewType: 'small', images: [lineItemImage('f6f4f1')] }],
  variationAttributes: [
    { id: 'color', name: 'Colour', values: [{ value: 'JJ5FUXX', name: 'Lilac Sand', orderable: true }] },
    { id: 'size', name: 'Size', values: [{ value: 'ONESIZE', name: 'One Size', orderable: true }] },
  ],
  variationValues: { color: 'JJ5FUXX', size: 'ONESIZE' },
};

const MOCK_LINE_ITEM_TWO = {
  ...MOCK_LINE_ITEM,
  itemId: 'b2c3d4e5f6a1b2c3d4e5f6a1',
  productId: '25601452M',
  id: '25601452M',
  productName: 'Ivory Linen Wide-Leg Trouser',
  name: 'Ivory Linen Wide-Leg Trouser',
  price: 395,
  priceAfterItemDiscount: 395,
  pricePerUnit: 395,
  quantity: 2,
  imageGroups: [{ viewType: 'small', images: [lineItemImage('f9f8f6')] }],
  variationAttributes: [
    { id: 'color', name: 'Colour', values: [{ value: 'IVR', name: 'Ivory', orderable: true }] },
    { id: 'size', name: 'Size', values: [{ value: '2', name: '2', orderable: true }] },
  ],
  variationValues: { color: 'IVR', size: '2' },
};

const meta: Meta<typeof ProductItem> = {
  title: 'Commerce/ProductItem',
  component: ProductItem,
  parameters: { layout: 'padded' },
  decorators: [WithProviders],
  args: {
    onItemQuantityChange: fn(async () => true),
  },
};

export default meta;
type Story = StoryObj<typeof ProductItem>;

export const Default: Story = {
  args: {
    product: MOCK_LINE_ITEM,
    primaryAction: <button type="button">Remove</button>,
  },
};

export const MultipleItems: Story = {
  render: (args) => (
    <>
      <ProductItem {...args} product={MOCK_LINE_ITEM} primaryAction={<button type="button">Remove</button>} />
      <ProductItem {...args} product={MOCK_LINE_ITEM_TWO} primaryAction={<button type="button">Remove</button>} />
    </>
  ),
};

